function stateForCloud(){return{...state,uid:user.uid,trip:tripForCloud(state.trip)}}
function syncProgress(){if(!user||!state)return Promise.resolve();const owner=user.uid,payload=stateForCloud();progressWrite=progressWrite.catch(()=>{}).then(()=>setDoc(doc(db,'progress',owner),payload,{merge:false})).catch(error=>console.warn('Não foi possível salvar o progresso na nuvem:',error.code||error.message));return progressWrite}
async function restoreProgress(){const local=load();try{const snapshot=await getDoc(doc(db,'progress',user.uid));if(!snapshot.exists())return local;const remote=snapshot.data();return{...fresh(),...remote,history:Array.isArray(remote.history)?remote.history:[],ledger:Array.isArray(remote.ledger)?remote.ledger:[],trip:tripFromCloud(remote.trip)}}catch(error){console.warn('Não foi possível restaurar o progresso da nuvem:',error.code||error.message);return local}}function normalizeCloudState(remote){return{...fresh(),...remote,history:Array.isArray(remote.history)?remote.history:[],ledger:Array.isArray(remote.ledger)?remote.ledger:[],trip:tripFromCloud(remote.trip)}}function watchProgress(){progressStop?.();const owner=user.uid;progressStop=onSnapshot(doc(db,'progress',owner),snapshot=>{if(!snapshot.exists()||!user||user.uid!==owner||!state)return;const remote=snapshot.data();if((Number(remote.savedAt)||0)<=(Number(state.savedAt)||0))return;state=normalizeCloudState(remote);localStorage.setItem(key(),JSON.stringify(state));chrome();route()},error=>console.warn('Sincronização entre dispositivos indisponível:',error.code||error.message))}
async function syncPresence(){if(!user||!state)return;const fuelChanged=updateTripFuel();if(fuelChanged){state.savedAt=Date.now();localStorage.setItem(key(),JSON.stringify(state));syncProgress()}try{await setDoc(doc(db,'players',user.uid),{uid:user.uid,name:user.displayName||'Motorista',photo:user.photoURL||'',level:level(state.xp),balance:state.balance,assets:purchasedAssetsValue(),investmentValue:investmentHoldingsValue(),km:state.km,deliveries:state.deliveries,truck:currentTruck().name,missionPoints:Number(state.missionPoints)||0,companyReputation:state.companyReputation&&typeof state.companyReputation==='object'?state.companyReputation:{},city:state.city,destination:state.trip?.to||'',company:state.trip?.company||'',companyName:state.companyName||'',trip:tripForCloud(state.trip),status:state.trip?'Em viagem':'Online',lastSeen:serverTimestamp()},{merge:true})}catch(error){console.warn('Presença multiplayer indisponível:',error.code||error.message)}}
function watchPresence(){presenceStop?.();marketStop?.();offerStateStop?.();clearInterval(presenceTimer);try{presenceStop=onSnapshot(collection(db,'players'),snapshot=>{allPlayers=snapshot.docs.map(item=>{const data=item.data();return{...data,uid:data.uid||item.id,name:data.name||data.displayName||'Motorista',city:data.city||'Jundiaí',trip:tripFromCloud(data.trip)}});onlinePlayers=allPlayers;if(location.hash.startsWith('#cidade/'))cityPage(decodeURIComponent(location.hash.slice(8)));if(location.hash==='#ranking')ranking();if(location.hash==='#mensagens')messagesPage();if(location.hash==='#mapa')renderLiveDrivers()},error=>{console.warn('Não foi possível acompanhar os motoristas:',error.code||error.message);toast('Não foi possível atualizar os outros jogadores agora.')})}catch(error){console.warn('Presença multiplayer indisponível:',error.code||error.message)}syncPresence();presenceTimer=setInterval(syncPresence,15000)}
