function updateTopFuel(){if(!state)return;const truck=currentTruck(),level=fuelLevel(),pct=truck.fuelCapacity?Math.max(0,Math.min(100,level/truck.fuelCapacity*100)):0,value=$('#top-fuel-value'),bar=$('#top-fuel-bar'),panel=document.querySelector('.top-fuel');if(value)value.textContent=level.toFixed(1).replace('.',',')+' / '+truck.fuelCapacity+' L';if(bar)bar.style.width=pct+'%';panel?.classList.toggle('warning',pct<=25);panel?.classList.toggle('critical',pct<=10)}function chrome(){const p=progress();updateTopFuel();$('#top-balance').textContent=money(state.balance);$('#user-name').textContent=(user.displayName||'Motorista').split(' ')[0];$('#top-level').textContent='Nível '+p.l;$('#user-photo').src=user.photoURL||avatar(user.displayName||'M');$('.location b').textContent=cityLabel(state.city);$('.side-status').classList.toggle('working',!!state.trip);$('.side-status span').innerHTML=state.trip?companyLogoByName(state.trip.company)+'<b>Em entrega</b><small>'+state.trip.company+' · '+state.trip.to+'</small>':'Base '+state.city+'<small>Conectado · operação normal</small>'}
