function activeWarehouse(city){ensureTradeState();const item=state.warehouses[city];if(!item)return null;if(item.type==='owned'||Number(item.expiresAt)>Date.now())return item;return null}
function warehouseCapacity(city){const item=activeWarehouse(city);return item?.type==='owned'?OWNED_WAREHOUSE_CAPACITY:item?RENTED_WAREHOUSE_CAPACITY:0}
function warehousePallets(city){ensureTradeState();return Array.isArray(state.warehouseStock[city])?state.warehouseStock[city]:[]}
function truckPalletLimit(truckId=state?.truck||'tia'){return truckCatalog[truckId]?.pallets||PALLET_LIMIT}function truckPalletCount(){ensureTradeState();return state.truckPallets.length}
function cocaPalletMarket(){const names=Object.keys(cities),day=offerCycleKey(),shuffled=[...names],rng=offerRandom('coca-pallet-'+day);for(let i=shuffled.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]]}const amount=Math.max(5,Math.min(10,Math.floor(names.length*.16))),sellers=shuffled.slice(0,amount).map((city,index)=>({city,price:Math.round((780+rng()*170)/10)*10,stock:3+Math.floor(rng()*5),side:'sell',index})),buyers=shuffled.slice(amount,amount*2).map((city,index)=>({city,price:Math.round((1180+rng()*270)/10)*10,demand:2+Math.floor(rng()*6),side:'buy',index}));return{day,sellers,buyers}}
function cocaOfferForCity(city){const market=cocaPalletMarket();return market.sellers.find(item=>item.city===city)||market.buyers.find(item=>item.city===city)||null}
function purchasedAssetsValue(){ensureTradeState();const trucks=ownedTruckIds().reduce((sum,id)=>sum+(Number(truckCatalog[id]?.price)||0),0),warehouses=Object.values(state.warehouses).filter(item=>item?.type==='owned').reduce((sum,item)=>sum+(Number(item.price)||WAREHOUSE_BUY_PRICE),0),pallets=[...state.truckPallets,...Object.values(state.warehouseStock).flatMap(items=>Array.isArray(items)?items:[])].reduce((sum,item)=>sum+(Number(item.cost)||0),0);const investments=investmentHoldingsValue();return trucks+warehouses+pallets+investments}
const deliveryPalletImages={CC:{image:'assets/items/coca-cola-pallet.png',alt:'Palete de produtos Coca-Cola',label:'PALETE DE COCA-COLA'},KL:{image:'assets/items/klabin-cellulose-pallet.png',alt:'Palete de celulose da Klabin',label:'PALETE DE CELULOSE'},FI:{image:'assets/items/fini-assorted-candy-pallet.png',alt:'Palete de diversos doces da Fini',label:'PALETE DE DIVERSOS DOCES'},BO:{image:'assets/items/bosch-drill-pallet.png',alt:'Palete de parafusadeiras Bosch Professional',label:'PALETE DE PARAFUSADEIRAS BOSCH'},PI:{image:'assets/items/pirelli-tire-pallet.png',alt:'Palete de pneus Pirelli',label:'PALETE DE PNEUS PIRELLI'},SA:{image:'assets/items/samsung-galaxy-a17-5g-pallet.png',alt:'Palete de smartphones Samsung Galaxy A17 5G',label:'PALETE DE SAMSUNG GALAXY A17 5G'},VW:{image:'assets/items/volkswagen-engine-parts-pallet.png',alt:'Palete de peças de motor Volkswagen',label:'PALETE DE PEÇAS DE MOTOR VOLKSWAGEN'},MB:{image:'assets/items/mercedes-benz-engine-parts-pallet.png',alt:'Palete de peças de motor da Mercedes-Benz',label:'PALETE DE PEÇAS DE MOTOR DA MERCEDES-BENZ'},BA:{image:'assets/items/bauducco-wafer-pallet.png',alt:'Palete de caixas de Wafer Bauducco',label:'PALETE DE CAIXAS DE WAFER BAUDUCCO'},TY:{image:'assets/items/toyota-automotive-parts-pallet.png',alt:'Palete de Peças Automotivas Toyota',label:'PALETE DE PEÇAS AUTOMOTIVAS TOYOTA'},UN:{image:'assets/items/unipar-pvc-resin-bags-pallet.png',alt:'Palete de Sacos de Resina PVC Unipar',label:'PALETE DE SACOS DE RESINA PVC UNIPAR'},CL:{image:'assets/items/ciclo-camil-rice-pallet.png',alt:'Palete de fardos de Arroz Camil com 6 unidades',label:'PALETE DE FARDOS DE ARROZ CAMIL'},US:{image:'assets/items/usiminas-hot-rolled-steel-coils-pallet.png',alt:'Palete de Bobinas de aço laminado a quente da Usiminas',label:'PALETE DE BOBINAS DE AÇO LAMINADO A QUENTE'},YA:{image:'assets/items/yara-yaramila-npk-fertilizer-pallet.png',alt:'Palete de Fertilizante NPK YaraMila',label:'PALETE DE FERTILIZANTE NPK YARAMILA'},BD:{image:'assets/items/bridgestone-passenger-car-tires-pallet.png',alt:'Palete de pneus Bridgestone para carros',label:'PALETE DE PNEUS BRIDGESTONE PARA CARROS'},PE:{image:'assets/items/pepsico-ruffles-pallet.png',alt:'Palete de Ruffles da PepsiCo',label:'PALETE DE RUFFLES'},HE:{image:'assets/items/heineken-beer-pallet.png',alt:'Palete de Cerveja Heineken',label:'PALETE DE CERVEJA HEINEKEN'},JB:{image:'assets/items/jbs-friboi-beef-pallet.png',alt:'Palete refrigerado de Carne bovina Friboi',label:'PALETE DE CARNE BOVINA FRIBOI'},HS:{image:'assets/items/hersheys-cookies-pallet.png',alt:'Palete de Hershey’s Cookies',label:'PALETE DE HERSHEY’S COOKIES'},AC:{image:'assets/items/ache-alenia-pallet.png',alt:'Palete de medicamento Alenia da Aché',label:'PALETE DE ALENIA'},CU:{image:'assets/items/cummins-diesel-engines-pallet.png',alt:'Palete de Motores diesel Cummins',label:'PALETE DE MOTORES DIESEL CUMMINS'},ML:{image:'assets/items/mercado-livre-diverse-items-pallet.png',alt:'Palete de caixas com diversos itens do Mercado Livre',label:'PALETE DE DIVERSOS ITENS'},AZ:{image:'assets/items/amazon-diverse-items-pallet.png',alt:'Palete de caixas com diversos itens da Amazon',label:'PALETE DE DIVERSOS ITENS'},NS:{image:'assets/items/nestle-ninho-integral-pallet.png',alt:'Palete de Ninho Integral da Nestlé',label:'PALETE DE NINHO INTEGRAL'},AB:{image:'assets/items/ambev-brahma-cans-pallet.png',alt:'Palete de Cerveja Brahma em latinhas da Ambev',label:'PALETE DE CERVEJA BRAHMA EM LATINHAS'},NA:{image:'assets/items/natura-ekos-pallet.png',alt:'Palete de produtos Natura Ekos',label:'PALETE DE NATURA EKOS'}};
const genericDeliveryPallet={image:'assets/items/generic-freight-pallet.png',alt:'Palete comum com mercadorias variadas',label:'PALETE DE MERCADORIAS'};
function companyCodeByName(name){if(!name)return'';if(name==='Volkswagen Anchieta')return'VW';return famousCompanies().find(company=>company.name===name)?.code||''}function deliveryCodeForTrip(trip){return trip?.companyCode||companyCodeByName(trip?.company)}function deliveryCargoVisual(code,compact=false){const cargo=deliveryPalletImages[code]||genericDeliveryPallet,pallets=truckPalletLimit(),label=pallets+' '+(pallets===1?cargo.label:cargo.label.replace('PALETE ','PALETES '));return'<div class="delivery-product-visual '+(compact?'compact':'')+'"><img src="'+cargo.image+'" alt="'+cargo.alt+'"><div><b>'+label+'</b><small>CARGA CONTRATADA DA ENTREGA</small></div></div>'}
function palletInventoryHTML(items,limit=PALLET_LIMIT,compact=false){const list=Array.isArray(items)?items:[];return'<div class="pallet-inventory '+(compact?'compact':'')+'>'+Array.from({length:limit},(_,index)=>{const item=list[index];return'<article class="pallet-slot '+(item?'occupied':'empty')+'">'+(item?'<img src="assets/items/coca-cola-pallet.png" alt="Palete de Coca-Cola"><div><b>PALETE DE COCA-COLA</b><small>Comprado em '+escapeHTML(item.boughtIn||'cidade não informada')+' · custo '+money(Number(item.cost)||0)+'</small></div>':'<div><b>ESPAÇO VAZIO</b><small>Capacidade disponível</small></div>')+'</article>'}).join('')+'</div>'}
function warehouseSection(city){ensureTradeState();const item=state.warehouses[city],active=activeWarehouse(city),stock=warehousePallets(city),here=state.city===city,expired=item?.type==='rented'&&!active,expiry=active?.type==='rented'?new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short'}).format(new Date(active.expiresAt)):'';return'<section class="warehouse-city"><div class="section-head"><div><h2>GALPÃO LOGÍSTICO</h2><span>COMPRE OU ALUGUE ESPAÇO NESTA CIDADE</span></div><b>'+(active?(active.type==='owned'?'GALPÃO PRÓPRIO':'ALUGADO ATÉ '+expiry):expired?'ALUGUEL VENCIDO':'SEM GALPÃO')+'</b></div>'+(active?'<div class="warehouse-overview"><article><span>ESTOQUE</span><strong>'+stock.length+' / '+warehouseCapacity(city)+' PALETES</strong><small>'+stock.filter(item=>item.product==='coca-cola').length+' de Coca-Cola</small>'+palletInventoryHTML(stock,Math.min(warehouseCapacity(city),10),true)+'</article><article><span>NO CAMINHÃO</span><strong>'+truckPalletCount()+' / '+truckPalletLimit()+' PALETES</strong><small>Este caminhão carrega até '+truckPalletLimit()+' paletes</small></article><div class="warehouse-actions">'+(here?'<button data-unload-pallet="'+escapeHTML(city)+'" '+(!state.truckPallets.length||stock.length>=warehouseCapacity(city)?'disabled':'')+'>DESCARREGAR NO GALPÃO</button><button data-load-pallet="'+escapeHTML(city)+'" '+(!stock.length||truckPalletCount()>=truckPalletLimit()?'disabled':'')+'>CARREGAR NO CAMINHÃO</button>':'<p>Viaje até esta cidade para movimentar o estoque.</p>')+'</div></div>':'<div class="warehouse-purchase"><p>Galpões próprios armazenam '+OWNED_WAREHOUSE_CAPACITY+' pallets e entram no patrimônio. O aluguel custa '+money(WAREHOUSE_RENT_PRICE)+' por semana e dura '+WAREHOUSE_RENT_DAYS+' dias contados a partir do pagamento. O galpão alugado armazena '+RENTED_WAREHOUSE_CAPACITY+' pallets e não entra no ranking.</p><button data-buy-warehouse="'+escapeHTML(city)+'" '+(!here?'disabled':'')+'>COMPRAR · '+money(WAREHOUSE_BUY_PRICE)+'</button><button data-rent-warehouse="'+escapeHTML(city)+'" '+(!here?'disabled':'')+'>'+(expired?'RENOVAR':'ALUGAR')+' · '+money(WAREHOUSE_RENT_PRICE)+'</button>'+(here?'':'<small>Você precisa estar na cidade para fechar o contrato.</small>')+'</div>')+'</section>'}
function cocaTradeSection(city){const offer=cocaOfferForCity(city),here=state.city===city;if(!offer)return'<section class="coca-city-market quiet"><div><span>MERCADO DE PALETES · COCA-COLA</span><h2>Sem negociação nesta cidade hoje</h2><p>As cidades compradoras e vendedoras mudam diariamente à meia-noite de Brasília.</p></div></section>';const selling=offer.side==='sell';return'<section class="coca-city-market '+offer.side+'"><div>'+companyLogo(famousCompanies().find(item=>item.code==='CC'),true)+'<div><span>MERCADO DIÁRIO · '+(selling?'VENDA':'COMPRA')+'</span><h2>'+(selling?'Paletes disponíveis':'Cidade procurando estoque')+'</h2><p>'+(selling?'Compre aqui e transporte até seu galpão ou uma cidade compradora.':'Chegue com pallets de Coca-Cola no caminhão para concluir a venda.')+'</p></div></div><aside><small>VALOR POR PALETE</small><b>'+money(offer.price)+'</b><em>'+(selling?Math.max(0,offer.stock-(Number(state.palletTradeDaily.bought[city])||0))+' unidades disponíveis':Math.max(0,offer.demand-(Number(state.palletTradeDaily.sold[city])||0))+' unidades procuradas')+'</em>'+(here?'<button data-'+(selling?'buy':'sell')+'-coca="'+escapeHTML(city)+'" '+(selling?(truckPalletCount()>=truckPalletLimit()?'disabled':''):(truckPalletCount()<1?'disabled':''))+'>'+(selling?(truckPalletCount()>=truckPalletLimit()?'CAMINHÃO LOTADO':'COMPRAR 1 PALETE'):(truckPalletCount()<1?'SEM PALETE NO CAMINHÃO':'VENDER 1 PALETE'))+'</button>':'<small>Viaje até a cidade para negociar.</small>')+'</aside></section>'}
function buyWarehouse(city,type){if(state.trip||state.city!==city)return;ensureTradeState();const price=type==='owned'?WAREHOUSE_BUY_PRICE:WAREHOUSE_RENT_PRICE;if(state.balance<price){toast('Saldo insuficiente para este galpão.');return}const previous=state.warehouses[city],at=Date.now();state.balance-=price;state.warehouses[city]=type==='owned'?{type:'owned',price,acquiredAt:at}:{type:'rented',price,acquiredAt:at,expiresAt:at+WAREHOUSE_RENT_DAYS*86400000};state.warehouseStock[city]=warehousePallets(city);addLedger('debit',price,type==='owned'?'Compra de galpão':'Aluguel de galpão',city+' · '+(type==='owned'?'imóvel próprio':'contrato de '+WAREHOUSE_RENT_DAYS+' dias'),at,'warehouse-'+type+'-'+city+'-'+at);save();toast(type==='owned'?'Galpão comprado em '+city+'.':'Galpão alugado em '+city+' por '+WAREHOUSE_RENT_DAYS+' dias.');cityPage(city)}
function buyCocaPallet(city){if(state.trip||state.city!==city)return;ensureTradeState();const offer=cocaOfferForCity(city);if(offer?.side!=='sell')return;const bought=Number(state.palletTradeDaily.bought[city])||0;if(bought>=offer.stock){toast('O estoque de hoje acabou nesta cidade.');return}if(truckPalletCount()>=truckPalletLimit()){toast('O caminhão atingiu o limite de '+truckPalletLimit()+' paletes.');return}if(state.balance<offer.price){toast('Saldo insuficiente para comprar o palete.');return}state.balance-=offer.price;state.palletTradeDaily.bought[city]=bought+1;state.truckPallets.push({id:String(Date.now())+'-'+Math.random(),product:'coca-cola',name:'Palete de Coca-Cola',cost:offer.price,boughtAt:Date.now(),boughtIn:city});addLedger('debit',offer.price,'Compra de palete Coca-Cola',city+' · carregado no caminhão',Date.now(),'pallet-buy-'+Date.now());save();toast('Palete comprado e carregado. Capacidade: '+truckPalletCount()+'/'+truckPalletLimit()+'.');cityPage(city)}
function sellCocaPallet(city){if(state.trip||state.city!==city)return;ensureTradeState();const offer=cocaOfferForCity(city),index=state.truckPallets.findIndex(item=>item.product==='coca-cola');if(offer?.side!=='buy'||index<0)return;const sold=Number(state.palletTradeDaily.sold[city])||0;if(sold>=offer.demand){toast('A procura de hoje já foi atendida nesta cidade.');return}state.palletTradeDaily.sold[city]=sold+1;const pallet=state.truckPallets.splice(index,1)[0],profit=offer.price-(Number(pallet.cost)||0);state.balance+=offer.price;addLedger('credit',offer.price,'Venda de palete Coca-Cola',city+' · resultado '+(profit>=0?'+':'')+money(profit),Date.now(),'pallet-sale-'+Date.now());save();toast('Palete vendido por '+money(offer.price)+'! Lucro: '+money(profit)+'.');cityPage(city)}
function movePallet(city,direction){if(state.trip||state.city!==city||!activeWarehouse(city))return;ensureTradeState();const stock=warehousePallets(city);if(direction==='unload'){if(!state.truckPallets.length||stock.length>=warehouseCapacity(city))return;stock.push(state.truckPallets.shift())}else{if(!stock.length||truckPalletCount()>=truckPalletLimit())return;state.truckPallets.push(stock.shift())}state.warehouseStock[city]=stock;save();toast(direction==='unload'?'Palete guardado no galpão.':'Palete carregado no caminhão.');cityPage(city)}
function bindTradeCityActions(city){document.querySelector('[data-buy-warehouse]')?.addEventListener('click',()=>buyWarehouse(city,'owned'));document.querySelector('[data-rent-warehouse]')?.addEventListener('click',()=>buyWarehouse(city,'rented'));document.querySelector('[data-buy-coca]')?.addEventListener('click',()=>buyCocaPallet(city));document.querySelector('[data-sell-coca]')?.addEventListener('click',()=>sellCocaPallet(city));document.querySelector('[data-unload-pallet]')?.addEventListener('click',()=>movePallet(city,'unload'));document.querySelector('[data-load-pallet]')?.addEventListener('click',()=>movePallet(city,'load'))}
function cityDailySection(name){const offers=availableOffersForCity(name);return'<section class="city-factories daily-city-jobs"><div class="section-head"><h2>'+offers.length+' ENTREGA'+(offers.length===1?'':'S')+' DISPONÍVEL'+(offers.length===1?'':'IS')+'</h2><span>ESTOQUE GLOBAL · IGUAIS PARA TODOS · RENOVAÇÃO À MEIA-NOITE</span></div><div class="factory-grid">'+offers.map(offer=>{const rw=marketReward(offer.km,offer.company.code);return'<article class="factory-card daily-delivery-card"><div class="factory-top">'+companyLogo(offer.company)+'<span>ÍNDICE '+formatMarketIndex(rw.factor)+'</span></div><h3>'+escapeHTML(offer.cargo)+'</h3>'+deliveryCargoVisual(offer.company.code,true)+'<p><b>'+escapeHTML(offer.company.name)+'</b><br>'+escapeHTML(name)+' → '+escapeHTML(offer.to)+'</p><small>'+(offer.ferry?'BALSA · ':'')+offer.km+' KM · '+travelTime(offer.km).toUpperCase()+' · '+money(rw.pay)+' + '+money(fuelCostFor(offer.km))+' combustível · +'+rw.xp+' XP</small><button data-daily-company="'+offer.company.code+'">VER EMPRESA</button></article>'}).join('')+'</div></section>'}function companiesPage(){const catalog=famousCompanies(),total=marketChoiceTotal;$('#view').innerHTML=heading('MERCADO DE FRETES','Empresas','As marcas principais do jogo e o índice fictício definido pelas entregas dos jogadores.')+'<section class="market-summary"><article><span>EMPRESAS PRINCIPAIS</span><b>'+catalog.length+'</b><small>marcas disponíveis nas ofertas</small></article><article><span>ESCOLHAS REGISTRADAS</span><b>'+total+'</b><small>atividade de todos os jogadores</small></article><article><span>PRÓXIMA RENOVAÇÃO</span><b>00:00</b><small>horário de Brasília</small></article></section><section class="game-market"><header><div><span><i></i>MERCADO FICTÍCIO DO JOGO</span><h2>Índice de fretes</h2><p>Índice permanente e balanceado: a escolhida perde até 4 pontos, sem ficar abaixo de 60%, e somente os pontos realmente retirados são distribuídos entre as demais empresas disponíveis. Em 60%, nenhuma pontuação é retirada ou distribuída. Limites de 60% a 140%.</p></div></header><div class="market-index-grid">'+catalog.map(factory=>{const factor=marketMultiplier(factory.code),count=Number(marketSelections[factory.code])||0,trend=factor>=1?'up':'down';return'<button class="market-company '+trend+'" data-company-code="'+factory.code+'">'+companyLogo(factory,true)+'<div><span>'+escapeHTML(factory.sector.toUpperCase())+'</span><h3>'+escapeHTML(factory.name)+'</h3><small>'+count+' ESCOLHA'+(count===1?'':'S')+' ACUMULADA'+(count===1?'':'S')+'</small></div><aside><b>'+formatMarketIndex(factor)+'</b><small>ÍNDICE DE PAGAMENTO</small></aside></button>'}).join('')+'</div></section>';document.querySelectorAll('[data-company-code]').forEach(button=>button.onclick=()=>location.hash='empresa/'+button.dataset.companyCode)}
function companyReputationProgress(value){const points=Math.max(0,Math.floor(Number(value)||0));let level=1,current=points,required=5;while(current>=required){current-=required;level++;required=Math.max(required+1,Math.ceil(required*1.12))}return{points,level,current,required,pct:Math.min(100,current/required*100)}}function companyReputation(code){if(!state.companyReputation||typeof state.companyReputation!=='object')state.companyReputation={};return companyReputationProgress(state.companyReputation[code])}function addCompanyReputation(companyName){const factory=famousCompanies().find(item=>item.name===companyName);if(!factory)return null;if(!state.companyReputation||typeof state.companyReputation!=='object')state.companyReputation={};const before=companyReputation(factory.code);state.companyReputation[factory.code]=before.points+1;const after=companyReputation(factory.code);return{...after,leveled:after.level>before.level,company:factory.name}}function companyDetailsPage(code){const factory=famousCompanies().find(item=>item.code===code);if(!factory){location.hash='empresas';return}const jobs=companyDailyJobs(code),factor=marketMultiplier(code),count=Number(marketSelections[code])||0,reputation=companyReputation(code);$('#view').innerHTML=heading('EMPRESA DO JOGO',factory.name,'Encontre primeiro as cargas mais próximas da sua localização atual.')+'<button class="back-map" data-back-companies>← VOLTAR ÀS EMPRESAS</button><section class="company-detail"><header>'+companyLogo(factory)+'<div><span>'+escapeHTML(factory.sector.toUpperCase())+'</span><h2>'+escapeHTML(factory.name)+'</h2><p>'+escapeHTML(factory.products)+'</p></div><aside><b>'+formatMarketIndex(factor)+'</b><small>ÍNDICE DE PAGAMENTO</small><em>'+count+' escolhas acumuladas</em></aside></header><section class="company-reputation"><div><span>SUA REPUTAÇÃO COM ESTA EMPRESA</span><b>NÍVEL '+reputation.level+'</b><small>'+reputation.current+' / '+reputation.required+' entregas para o próximo nível</small></div><strong>'+reputation.points+' ENTREGA'+(reputation.points===1?'':'S')+' CONCLUÍDA'+(reputation.points===1?'':'S')+'</strong><i><em style="width:'+reputation.pct+'%"></em></i><p>A reputação não possui nível máximo. No momento ela registra apenas sua experiência com a empresa, sem conceder bônus.</p></section><div class="section-head company-jobs-head"><div><h2>ONDE ENCONTRAR ESTA CARGA</h2><span>ORDENADO DA COLETA MAIS PRÓXIMA PARA A MAIS DISTANTE</span></div><b>'+jobs.length+' OFERTAS HOJE</b></div><div class="company-job-list">'+(jobs.length?jobs.map((job,index)=>{const rw=marketReward(job.km,job.company.code),here=job.city===state.city,pickup=here?'VOCÊ ESTÁ NESTA CIDADE':Number.isFinite(job.pickupDistance)?job.pickupDistance+' KM ATÉ A COLETA':'SEM ROTA DIRETA';return'<article class="company-job-card '+(here?'pickup-here':'')+'"><header><div><span>'+(index===0?'MAIS PRÓXIMA · ':'')+'COLETA EM '+escapeHTML(job.city.toUpperCase())+'</span><h3>'+escapeHTML(job.cargo)+'</h3><p>'+escapeHTML(job.city)+' → '+escapeHTML(job.to)+' · '+job.km+' km de entrega · '+travelTime(job.km)+'</p></div><strong>'+escapeHTML(pickup)+'</strong></header>'+deliveryCargoVisual(job.company.code,true)+'<footer><div><small>FRETE</small><b>'+money(rw.pay)+'</b></div><div><small>COMBUSTÍVEL</small><b>+'+money(fuelCostFor(job.km))+'</b></div><div><small>EXPERIÊNCIA</small><b>+'+rw.xp+' XP</b></div><button data-pickup-city="'+escapeHTML(job.city)+'">'+(here?'VER ENTREGAS DESTA CIDADE':'VER CIDADE DE COLETA')+'</button></footer></article>'}).join(''):'<p class="ranking-empty">Esta empresa não possui contratos sorteados hoje. Seu índice poderá subir quando outras marcas forem escolhidas.</p>')+'</div></section>';document.querySelector('[data-back-companies]').onclick=()=>location.hash='empresas';document.querySelectorAll('[data-pickup-city]').forEach(button=>button.onclick=()=>location.hash=button.dataset.pickupCity===state.city?'entregas':'cidade/'+encodeURIComponent(button.dataset.pickupCity))}fu