function ensureInvestmentState(){if(!state)return;if(!state.investments||typeof state.investments!=='object'||Array.isArray(state.investments))state.investments={};if(!state.investmentLots||typeof state.investmentLots!=='object'||Array.isArray(state.investmentLots))state.investmentLots={};Object.keys(state.investments).forEach(code=>{const quantity=Math.max(0,Math.floor(Number(state.investments[code])||0));if(!investmentCatalog[code]||!quantity){delete state.investments[code];delete state.investmentLots[code];return}state.investments[code]=quantity;const lots=Array.isArray(state.investmentLots[code])?state.investmentLots[code].map(lot=>({quantity:Math.max(0,Math.floor(Number(lot?.quantity)||0)),boughtAt:Number(lot?.boughtAt)||Date.now()})).filter(lot=>lot.quantity):[],tracked=lots.reduce((sum,lot)=>sum+lot.quantity,0);if(tracked<quantity)lots.push({quantity:quantity-tracked,boughtAt:Date.now()});else if(tracked>quantity){let excess=tracked-quantity;for(let index=lots.length-1;index>=0&&excess>0;index--){const removed=Math.min(excess,lots[index].quantity);lots[index].quantity-=removed;excess-=removed} }state.investmentLots[code]=lots.filter(lot=>lot.quantity)});Object.keys(state.investmentLots).forEach(code=>{if(!state.investments[code])delete state.investmentLots[code]});if(typeof state.lastDividendOn!=='string')state.lastDividendOn=''}
