const loanPlans={8:{rate:.08},16:{rate:.18},24:{rate:.30},36:{rate:.48}};function loanQuote(weeks){const plan=loanPlans[weeks],total=Math.round(45000*(1+plan.rate)),weekly=Math.ceil(total/weeks);return{weeks:+weeks,rate:plan.rate,total,weekly}}
function truckShop(){const saleIds=['agrale8500','mercedes710','volkswagen8150','scaniaT113'],cards=saleIds.map(id=>{const truck=truckCatalog[id],owned=ownsTruck(id),active=state.truck===id,label=active?'CAMINHÃO EM USO':owned?'USAR ESTE CAMINHÃO':'COMPRAR POR '+money(truck.price);return'<section class="dealer-card"><div class="dealer-photo"><img src="'+truck.image+'" alt="'+truck.name+'"><span>SEMINOVO</span></div><div class="dealer-info"><p class="eyebrow">'+(id==='scaniaT113'?'CAMINHÃO RODOVIÁRIO · 4X2':'CAMINHÃO LEVE · 4X2')+'</p><h2>'+truck.name+'</h2><strong class="dealer-price">'+money(truck.price)+'</strong><p>'+truck.description+'</p><dl><div><dt>ALCANCE NO JOGO</dt><dd>'+truck.range+' km</dd></div><div><dt>VELOCIDADE MÁXIMA</dt><dd>'+truck.speed+' km/h</dd></div><div><dt>CAPACIDADE DE PALETES</dt><dd>'+truck.pallets+' paletes</dd></div><div><dt>BÔNUS NO FRETE</dt><dd>'+(truck.pallets>1?'+'+((truck.pallets-1)*25)+'%':'Normal')+'</dd></div><div><dt>TANQUE DE COMBUSTÍVEL</dt><dd>'+truck.fuelCapacity+' litros</dd></div></dl><button data-dealer-truck="'+id+'" '+(active?'disabled':'')+'>'+label+'</button><small>Seu saldo atual: '+money(state.balance)+'</small></div></section>'}).join('');$('#view').innerHTML=heading('CONCESSIONÁRIA LONER','Venda de caminhões','Compre veículos para aumentar sua capacidade e abrir novas rotas.')+'<div class="dealer-list">'+cards+'</div>';document.querySelectorAll('[data-dealer-truck]').forEach(button=>button.onclick=()=>selectOrBuyTruck(button.dataset.dealerTruck))}
