async function startCompanyContractTrip(button){if(state.trip)return;if(truckPalletCount()){toast('Descarregue ou venda os pallets antes de iniciar a entrega do contrato.');return}if(tireCondition()<=0){toast('Troque os pneus antes de iniciar a entrega do contrato.');return}const offer=companyContractOffer(),truck=currentTruck();if(!offer){toast('Não há rota contratual disponível a partir desta cidade.');return}if(!canFuelTrip(offer.km,truck)){toast('Combustível insuficiente. Abasteça o caminhão.');return}const from=state.city,startCity=cities[from],endCity=cities[offer.to];if(!startCity||!endCity)return;if(button){button.disabled=true;button.textContent='CALCULANDO ROTA...'}let path=[[startCity.lat,startCity.lng],[endCity.lat,endCity.lng]];try{const response=await fetch('https://router.project-osrm.org/route/v1/driving/'+startCity.lng+','+startCity.lat+';'+endCity.lng+','+endCity.lat+'?overview=full&geometries=geojson'),data=await response.json(),road=data.routes?.[0];if(road)path=road.geometry.coordinates.map(point=>[point[1],point[0]])}catch{}const rewardData=marketReward(offer.km,offer.company.code),start=Date.now(),duration=travelMinutes(offer.km),fuelStart=fuelLevel(),fuelPlanned=fuelLitersFor(offer.km,truck),fuelAllowance=fuelCostFor(offer.km,truck);state.trip={companyContract:true,truckId:state.truck,fuelStart,fuelPlanned,tireCondition:tireCondition(),from,to:offer.to,company:offer.company.name,companyCode:offer.company.code,cargo:offer.cargo,totalKm:offer.km,path,start,end:start+duration*60000,pay:rewardData.pay,fuelUsed:0,fuelAllowance,xp:rewardData.xp};save();toast('Entrega contratual da '+offer.company.name+' iniciada para '+offer.to+'.');location.hash='mapa'}
